insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('NL1','A','Nilai','Kamus UiTM 2021','pentadbiran','Berilmu','Pengetahuan dan kepandaian terhadap sesuatu perkara.','Program Pemantapan Nilai & Integriti UiTM (ILD)',1,null,1) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('NL2','A','Nilai','Kamus UiTM 2021','pentadbiran','Berdisiplin','Disiplin adalah suatu keadaan yang tercipta dan terbentuk melalui proses gabungan perilaku yang menunjukkan nilai-nilai ketaatan, keteraturan dan ketertiban.','Program Pemantapan Nilai & Integriti UiTM (ILD)',1,null,2) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('NL3','A','Nilai','Kamus UiTM 2021','pentadbiran','Beramanah','Amanah adalah satu tanggungjawab yang diberikan sebagai satu prinsip untuk tidak mengambil kesempatan dengan menggunakan pengaruh dan kuasa yang sedia ada (mumtaz, norzaini dan mohamed sani, 2010).','Program Pemantapan Nilai & Integriti UiTM (ILD)',1,null,3) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('NL4','A','Nilai','Kamus UiTM 2021','pentadbiran','Rajin','Bersungguh-sungguh dan tekun di dalam melaksanakan tanggungjawab.','Program Pemantapan Nilai & Integriti UiTM (ILD)',1,null,4) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('NL5','A','Nilai','Kamus UiTM 2021','pentadbiran','Bertanggungjawab','Suatu kewajipan atau tugasan yang mesti dilaksanakan.','Program Pemantapan Nilai & Integriti UiTM (ILD)',1,null,5) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('TR1','A','Teras','Kamus UiTM 2021','pentadbiran','Komunikasi Interpersonal','Komunikasi interpersonal adalah proses pertukaran maklumat, idea dan perasaan antara dua atau lebih orang melalui kaedah lisan atau bukan lisan termasuk pertukaran maklumat secara bersemuka, dalam bentuk suara, ekspresi wajah, bahasa badan dan gerak isyarat untuk mencapai objektif universiti.','Kursus Komunikasi Berkesan & Interpersonal',1,14,6) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('TR2','A','Teras','Kamus UiTM 2021','pentadbiran','Perkhidmatan Berorientasikan Pelanggan','Keupayaan dan kesediaan untuk mengetahui kemahuan dan keperluan pelanggan dan bertindak dengan sewajarnya, mengambil kira faedah kepada pencapaian objektif universiti.','Kursus Perkhidmatan Pelanggan Cemerlang',1,10,7) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('TR3','A','Teras','Kamus UiTM 2021','pentadbiran','Pemikiran Inovatif & Kreatif','Keupayaan dalam menjana dan menyumbang idea atau kaedah baharu bagi menyelesaikan masalah atau penambahbaikan aktiviti atau proses kerja, perkhidmatan atau produk bagi mencapai kecemerlangan universiti.','Kursus Pemikiran Kreatif & Inovatif',1,10,8) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('TR4','A','Teras','Kamus UiTM 2021','pentadbiran','Orientasi Keberhasilan','Keupayaan menjana tenaga, komitmen dan kesungguhan yang berterusan dalam menghadapi setiap halangan untuk mencapai sasaran yang mencabar, seiring dengan mematuhi kualiti, masa dan kepelbagaian piawaian dan hasil yang diperlukan bagi mencapai objektif universiti.','Kursus Pengurusan Prestasi & KPI',1,10,9) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('TR5','A','Teras','Kamus UiTM 2021','pentadbiran','Kerja Berpasukan','Keupayaan untuk bekerja dan berhubung dengan orang lain dalam pasukan, membantu dan menyumbangkan idea, mematuhi keputusan dan arahan kepimpinan untuk mencapai objektif dan sasaran yang ditetapkan oleh universiti.','Program Team Building / Kerja Berpasukan',1,10,10) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('GN1','A','Generik','Kamus UiTM 2021','pentadbiran','Pengurusan Sumber Manusia','Keupayaan merancang keperluan guna tenaga dan pembangunan sumber manusia serta keupayaan melaksana hal ehwal pentadbiran sumber manusia bagi mencapai kecemerlangan organisasi.','Kursus Pengurusan Sumber Manusia untuk Pengurus',12,null,11) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('GN2','A','Generik','Kamus UiTM 2021','pentadbiran','Pengurusan Operasi','Keupayaan merancang, melaksana dan menilai kecekapan dan keberkesanan operasi bahagian atau organisasi dan berupaya mewujudkan dan meningkatkan sistem penyampaian perkhidmatan yang cekap bagi mencapai objektif organisasi.','Kursus Pengurusan Operasi Pejabat',3,14,12) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('GN3','A','Generik','Kamus UiTM 2021','pentadbiran','Pengurusan Kewangan & Aset','Keupayaan merancang dan memperoleh sumber kewangan dan aset selaras degan keperluan organisasi dan mengawal dan memantau penggunaan sumber kewangan dan aset secara optimum untuk mencapai objektif organisasi.','Kursus Pengurusan Kewangan, Perolehan & Aset (Arahan Perbendaharaan)',3,14,13) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('GN4','A','Generik','Kamus UiTM 2021','pentadbiran','Penyediaan Dokumen Rasmi','Keupayaan menguasai bahasa dengan mahir dan menyampaikan maksud dengan jelas dan tepat serta merancang dan menyediakan dokumen rasmi yang jelas untuk tujuan penyampaian arahan, mesej yang tersirat mengikut garis panduan, prosedur dan piawaian untuk mencapai kecekapan pengurusan organisasi.','Kursus Penulisan Minit, Laporan & Kertas Cadangan',1,10,14) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('KP1','A','Kepimpinan','Kamus UiTM 2021','pentadbiran','Pemikiran Strategik','Pemikiran strategik adalah keupayaan seseorang untuk merancang masa depan. ia adalah keupayaan untuk menyiapkan strategi dan menghasilkan idea yang akan mengatasi perubahan persekitaran dan mempertimbangkan pelbagai cabaran masa hadapan.','Kursus Pemikiran Strategik',9,null,15) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('KP2','A','Kepimpinan','Kamus UiTM 2021','pentadbiran','Jaringan & Kolaborasi Strategik / Pengurusan Pemegang Taruh','Keupayaan mengembangkan jaringan dan kolaborasi strategik menang-menang dengan pelbagai pihak dan mengurus perhubungan dengan pihak berkepentingan bagi mencapai objektif universiti.','Kursus Stakeholder Management & Networking',9,null,16) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('KP3','A','Kepimpinan','Kamus UiTM 2021','pentadbiran','Membangunkan Pemimpin','Keupayaan mengenal pasti, membentuk dan membangunkan bakal pemimpin yang berpotensi dan cemerlang untuk mempersiapkan universiti dengan lapisan pemimpin dan memenuhi keperluan jangka panjang.','Kursus Coaching & Mentoring',9,null,17) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('KP4','A','Kepimpinan','Kamus UiTM 2021','pentadbiran','Penggubalan & Penguatkuasaan Dasar','Pemikiran strategik adalah keupayaan seseorang untuk merancang masa depan. ia adalah keupayaan untuk menyiapkan strategi dan menghasilkan idea yang akan mengatasi perubahan persekitaran dan mempertimbangkan pelbagai cabaran masa hadapan.','Kursus Penggubalan Polisi',12,null,18) on conflict (code) do nothing;
insert into tna_competencies (code, layer, cluster, source, staff_category, name_ms, definition_ms, default_training_ms, min_sspa_grade, max_sspa_grade, sort_order) values ('KP5','A','Kepimpinan','Kamus UiTM 2021','pentadbiran','Memimpin Perubahan','Memimpin perubahan adalah keupayaan membimbing bagaimana menyediakan, melengkapkan dan menyokong individu, pasukan dan organisasi untuk berjaya menerima pakai perubahan untuk memacu penghasilan visi, misi dan objektif universiti.','Kursus Change Management',12,null,19) on conflict (code) do nothing;
