insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL2',1,'Mematuhi peraturan pada tahap minimum; Memahami kepentingan menepati masa; Memahami adab dan etika.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL2',2,'Mematuhi peraturan berkaitan tugas yang ditetapkan; Melaksanakan tugas di dalam tempoh masa yang ditetapkan; Melaksanakan tugas dengan tekun mengikut peraturan yang ditetapkan; Melaksanakan tugas mengikut adab dan etika jabatan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL2',3,'Mematuhi peraturan dan arahan ketua tanpa persoalan; Melaksanakan arahan dengan penuh tanggungjawab & memastikan peraturan organisasi dipatuhi; Menjadi contoh kepada jabatan/fakulti di dalam perlaksanaan tugas.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL2',4,'Memastikan perlaksanan tugas yang sempurna; Mempamerkan disiplin diri yang unggul yang menjadi contoh; Membimbing staf fakulti/ universiti di dalam perlaksanaan tugas secara berdisiplin.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL2',5,'Meneraju organisasi ke arah etika dan imej yang terbaik; Membimbing warga organisasi ke arah budaya berdisiplin yang unggul; Memantau perlaksanaan disiplin di peringkat universiti/masyarakat.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL3',1,'Membuat pertimbangan secara rasional sebelum melaksanakan amanah; Menyiapkan kerja dalam tempoh yang ditetapkan dan tidak menggunakan masa pejabat untuk urusan peribadi; Memahami konsep dan kepentingan amanah dalam menjalankan tugas harian.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL3',2,'Menerima amanah secara sukarela; Menjalankan amanah dengan adil; Mengawal diri dan tidak melakukan sesuatu yang boleh menghilangkan kepercayaan orang lain.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL3',3,'Melaksanakan amanah secara telus; Menjaga kerahsiaan dalam melaksanakan amanah; Menjalankan tugas dengan penuh tanggungjawab tanpa penyelewengan dan kecuaian.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL3',4,'Menjaga hak pihak berkepentingan dalam amanah tersebut; Memberi keutamaan kepada kepentingan organisasi; Mengamalkan dasar tidak memilih kasih dalam menjalankan tugas.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL3',5,'Sentiasa boleh dipercayaai apabila diberi amanah; Menggalak dan membimbing organisasi ke arah integriti yang tinggi; Memasti dan memantau tahap perlaksanaan amanah di peringkat universiti/masyarakat.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL4',1,'Melaksanakan kerja mengikut keadaan dan emosi semasa; Menggunakan waktu dengan produktif - kerja siap pada masanya; Memberi tumpuan dalam menyiapkan tugasan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL4',2,'Melakukan kerja mengikut arahan ketua dari semasa ke semasa; Melaksanakan kerja dengan tekun dan kerjasama dengan pasukan; Membuat perancangan dengan teliti dalam melaksanakan sesuatu tugas,.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL4',3,'Memastikan hasil kerja memenuhi piawaian kualiti; Menyumbang idea untuk meningkatkan mutu kerja di peringkat unit/ bahagian/ jabatan; Menggunakan kreativiti dalam melaksanakan tugas.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL4',4,'Menyiapkan kerja dengan penuh komitmen tanpa mengira masa; Melaksanakan tanggungjawab di luar batasan waktu kerja formal untuk keperluan organisasi; Menambahbaik kualiti kerja.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL4',5,'Melaksanakan kerja yang diberikan melebihi jangkaan; Meneraju budaya kecemerlangan organisasi; Menggerakkan budaya berorientasikan pencapaian organisasi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL5',1,'Memahami kepentingan sifat bertanggungjawab yang diberikan; Menyiapkan tugasan dengan sempurna; Mematuhi peraturan/ proses kerja setiap masa.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL5',2,'Melaksanakan tanggungjawab yang diberikan dengan baik; Membantu rakan sekerja menyiapkan tugas; Menggunakan sumber dengan cekap dan berkesan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL5',3,'Memastikan berupaya melaksanakan tanggungjawab dengan berkesan; Menggerakkan inisiatif secara produktif tanpa diarah melakukannya; Mengajar rakan sekerja dalam perlaksanaan tugas.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL5',4,'Menghormati adab berbeza pendapat mengikut keadaan dan keperluan; Memupuk kerjasama dari pelbagai pihak di peringkat organisasi; Mewujudkan budaya bertanggungjwab di kalangan staf di peringkat organisasi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('NL5',5,'Mengamalkan akauntabiliti yang tinggi atas hasil kerja; Menilai keberkesanan setiap tugasan; Memantau keberkesanan budaya bertanggungjawab di dalam organisasi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR1',1,'Memberikan penjelasan dan penjelasan yang jelas, mudah difahami dan mencapai sasaran; Memberikan maklum balas yang tepat dan berhemah; Mendengar dan memahami dan dapat bertindak balas terhadap maklumbalas yang diterima.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR1',2,'Menyampaikan mesej dengan jelas, menggunakan nada suara dan bahasa badan yang betul yang sepadan dengan latar belakang dan keperluan kumpulan sasaran; Menyokong mesej dengan data atau maklumat yang relevan untuk mencipta komunikasi yang berkesan; Mengguna teknik yang sesuai untuk memupuk hubungan interpersonal yang harmoni.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR1',3,'Mendengar dengan sabar dan tenang dan dapat menangani isu-isu yang mencabar dan kompleks; Menganalisis maklumat yang tidak ketara, mentafsirkan isu-isu sebenar dan menyediakan pilihan yang tepat dan sesuai; Memudahcara untuk menyelesaikan konflik antara individu dalam pasukan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR1',4,'Menguruskan ekspedisi, menjangka tingkah laku dan memenangi hati personaliti yang mencabar dalam dan luar universiti; Menilai profil, kelemahan dan kekuatan kumpulan sasar serta mengaplikasikan teknik atau kaedah yang berkesan apabila berinteraksi dengan individu latar belakang yang berbeza dan berprofil tinggi untuk mewujudkan keharmonian dan kefahaman supaya ada hubungan berterusan yang positif dan berkesan; Menjana idea atau maklumat untuk mencapai penyelesaian yang berkesan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR1',5,'Membangunkan kaedah atau teknik terkini dan lebih berkesan untuk mewujudkan komunikasi interpersonal; Membimbing dan membangunkan pasukan pengurusan kanan yang berkemahiran aras tinggi di dalam komunikasi interpersonal; Memupuk budaya komunikasi interpersonal yang berasaskan nilai dan visi universiti.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR2',1,'Memahami keperluan dan harapan pelanggan Perkhidmatan universiti; Memahami intipati dan mesej yang tersirat dalam piagam pelanggan yang berkaitan dengan tugas dan tanggungjawab jawatan; Menjalankan tugas harian mengikut prosedur yang ditetapkan dan piagam pelanggan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR2',2,'Melengkapkan tugas yang diingini atau diperlukan oleh pelanggan dengan cekap dan berkualiti; Mengamalkan komunikasi etika dan protokol yang sesuai semasa berkomunikasi dengan pelanggan sama ada secara bersemuka, menulis atau telefon; Memberi maklum balas dan cadangan kepada ketua/ penyelia mengenai penambahbaikan penyampaian perkhidmatan kepada pelanggan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR2',3,'Memahami keperluan dan ekspektasi pelanggan yang berprofil tinggi dalam pelbagai situasi dan tuntutan yang lebih mencabar; Menganalisis isu-isu dalaman dan luaran yang memberi impak secara langsung atau tidak langsung kepada pelanggan; Memudahcara perhubungan dengan pihak atasan, rakan sekerja dan pelanggan mengenai keperluan sebenar yang perlu diberikan perhatian dan penekanan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR2',4,'Merangka dan melaksanakan strategi berkesan untuk membudayakan penekanan kepada pelanggan di dalam pelbagai aspek di semua peringkat; Memperkenalkan model atau sistem untuk mengumpul, menyusun dan mengintegrasi maklumat demografik pelanggan bertujuan membangunkan program yang bersesuaian dan bertepatan dengan profil kumpulan sasar; Membangunkan langkah-langkah intervensi yang proaktif dan konstruktif untuk menyampaikan perkhidmatan yang bersesuaian dengan gaya hidup pelanggan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR2',5,'Memupuk budaya kecemerlangan perkhidmatan berorientasikan pelanggan di kalangan warga universiti; Meneraju program-program perkhidmatan pelanggan berimpak tinggi; Menggerakkan inisiatif peringkat dalaman dan luaran universiti bagi merangka pendekatan-pendekatan baharu bagi mencapai kecemerlangan perkhidmatan pelanggan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR3',1,'Memahami dan menyokong konsep inovasi dalam menjalankan tugas dan tanggungjawab; Mengambil inisiatif untuk menambah baik proses dan pelaksanaan tugas sendiri; Menyokong pelaksanaan aktiviti atau usaha inovasi bagi memperbaiki proses dan cara kerja yang diperkenalkan oleh pihak pengurusan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR3',2,'Menyumbang tenaga dan masa untuk merealisasikan pelaksanaan inovasi dalam bahagian/ universiti; Mencadangkan idea atau kaedah baharu atau inovatif yang boleh menyelesaikan masalah atau menambah baik prestasi dan kualiti kerja di peringkat bahagian/ universiti; Melibatkan diri secara aktif dalam pelaksanaan aktiviti atau usaha inovasi bagi memperbaiki proses dan cara kerja yang diperkenalkan oleh pihak pengurusan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR3',3,'Menilai dan memperbaiki kaedah/ prosedur/ proses yang tidak berkesan untuk meningkatkan penyampaian perkhidmatan di peringkat universiti; Merancang dan mencadang strategi, program, kaedah atau proses baharu yang inovatif bagi memperbaiki perkhidmatan dan prestasi universiti; Menggalakkan penjanaan idea-idea inovatif yang baharu dan berbeza.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR3',4,'Menjangkakan serta mencetus idea dalam bentuk inovasi yang diperlukan oleh universiti di masa hadapan secara jangka masa panjang; Memudahcara dan membina keupayaan universiti untuk penjanaan dan pelaksanaan idea dan inovasi; Mewujudkan budaya inovasi yang fleksibel dan responsif untuk memenuhi kehendak perubahan dan trend masa hadapan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR3',5,'Menerajui dan menjuarai pembangunan di dalam pengurusan inovasi dan kreatif universiti; Menggerakkan inisiatif di peringkat universiti bagi membangunkan budaya inovatif dan kreatif; Membimbing pengurusan kanan di dalam memacu dan menjana pemikiran inovatif dan kreatif bagi warga universiti.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR4',1,'Memahami Petunjuk Prestasi Utama (KPI) dan sasaran kerja yang ditetapkan; Menerima dan melaksana arahan yang diberikan oleh ketua secara positif dan sukarela; Menerima teguran dan ulasan mengenai prestasi kerja secara terbuka dengan tujuan untuk memperbaiki diri.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR4',2,'Merancang dan mengurus aktiviti masa dan tindakan kerja selaras dengan Petunjuk Prestasi Utama (KPI) dan sasaran kerja; Melaksanakan aktiviti yang dirancang untuk mencapai sasaran yang telah ditetapkan dalam tempoh diberikan; Menyelesaikan isu dan masalah yang wujud dalam pelaksanaan kerja.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR4',3,'Menilai dan memperbaiki kaedah/ prosedur/ proses yang tidak berkesan untuk meningkatkan penyampaian perkhidmatan di peringkat universiti; Merancang dan mencadang strategi, program, kaedah atau proses baharu yang inovatif bagi memperbaiki perkhidmatan dan prestasi universiti; Menggalakkan penjanaan idea-idea inovatif yang baharu dan berbeza.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR4',4,'Menetap dan menggariskan strategi terbaik untuk mencapai hala tuju universiti; Mencipta peluang-peluang baharu melalui pendekatan inovatif untuk meningkatkan keberhasilan universiti; Menanda aras pembaharuan dan amalan baik untuk diadaptasi oleh bahagian/ universiti bagi kecemerlangan berterusan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR4',5,'Mewujudkan budaya berprestasi tinggi agar sentiasa melangkaui ekspektasi untuk kecemerlangan universiti; Mengiktiraf dan menghargai pembaharuan dan inovasi sebagai tanda aras untuk mewujudkan budaya berprestasi tinggi; Memupuk dan mempengaruhi pasukan untuk sentiasa menambah baik sistem pengurusan universiti secara lebih sistematik dan menyeluruh.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR5',1,'Memahami dan melaksanakan peranan dan tanggungjawab yang diamanahkan; Berkongsi pengetahuan, maklumat dan idea dengan ahli pasukan untuk menjayakan objektif pasukan; Memahami ahli-ahli pasukan dan peranan masing-masing.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR5',2,'Menyumbang idea, pendapat dan cadangan dalam pasukan; Mendengar dan berfikiran positif terhadap pandangan dan cadangan ahli pasukan; Memberikan bantuan dan sokongan yang diperlukan ke arah kecemerlangan program.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR5',3,'Merancang dan melaksana aktiviti-aktiviti yang mengeratkan hunbungan sesama ahli pasukan; Mengambil pendekatan menang-menang untuk menguruskan konflik antara pasukan; Memberi maklum balas dan galakan untuk meningkatkan prestasi dan mencapai objektif kerja.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR5',4,'Menilai strategi dan program pemantapan kerja berpasukan di peringkat bahagian/ universiti; Menyumbang tenaga, masa dan sumber yang perlu untuk merealisasikan misi dan usaha pasukan dalam situasi mencabar; Mengiktiraf dan menghargai segala usah untuk meningkatkan motivasi berpasukan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('TR5',5,'Menjalin kolaborasi strategik dalaman dan luaran di pelbagai peringkat untuk memantapkan kualiti dan prestasi pasukan. Mencipta pendekatan; strategik dan kaedah-kaedah baharu termasuk strategi perundingan berkesan untuk sinergi pasukan. Mengerakkan pendekatan menang-menang untuk; mengukuhkan perhubungan antara universiti dengan pelbagai agensi dalaman dan luaran.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN1',1,'Memahami Pengurusan Sumber Manusia secara menyeluruh dan strategik; Memberi tunjuk ajar dan latihan kepada pegawai-pegawai di bawah seliaan mengenai tugas-tugas yang telah ditetapkan; Memantau, mengawal selia dan memberi maklum balas mengenai tahap pencapaian prestasi kerja bagi pegawai-pegawai di bawah seliaan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN1',2,'Mengkaji kecekapan dan keberkesanan operasi pengurusan sumber manusia dari segi pencapaian prestasi, bilangan dan kualiti tenaga kerja sedia ada; Mengkaji dan menentukan skop dan keperluan spesifikasi tugas bagi setiap jawatan yang diselia; Mengambil tindakan proaktif untuk meningkatkan prestasi dan kualiti kakitangan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN1',3,'Membangunkan tahap kecekapan kompetensi setiap pegawai di bawah seliaan dan mencadangkan langkah-langkah yang sesuai untuk membangunkan tahap kecekapan kompetensi pegawai terbabit; Membangunkan strategi mantap yang mampu mengoptimumkan penggunaan sumber manusia sedia ada ke arah pencapaian keberhasilan yang ditetapkan; Merancang keperluan guna tenaga dan kompetensi sumber manusia untuk memenuhi keperluan operasi tahunan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN1',4,'Menganalisis keperluan dan menyediakan pelan dan rangka kerja strategik pengurusan bakat secara menyeluruh untuk Jabatan; Mengkaji dan menganalisis prestasi keseluruhan jabatan dan mencadangkan langkah-langkah proaktif dan konstruktif untuk meningkatkan prestasi, kecekapan dan keberkesanan bakat pegawai sedia ada; Menilai dan mengenal pasti bakat-bakat yang berpotensi tinggi secara efektif dan sistematik.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN1',5,'Menggerakkan pembangunan pegawai-pegawai berprestasi tinggi untuk membimbing, memupuk dan mengasah bakat-bakat tersebut ke arah menjadi pemimpin di dalaman dan luaran universiti; Memperkasa sistem pengurusan kerjaya dan pembangunan bakat yang menyeluruh dan inovatif demi menjamin kesinambungan kepimpinan tertinggi universiti; Meneraju budaya kecemerlangan bakat untuk mewujudkan universiti berprestasi tinggi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN2',1,'Memahami pendekatan dan kaedah pengurusan operasi yang bersistematik dan berkualiti; Merancang dan melaksana tugas-tugas operasi unit/jabatan menurut pelan dan bidang kuasa yang telah ditetapkan; Memantau dan mengawal selia tugas-tugas pegawai bawahan dan memastikan pelaksanaan tugas-tugas tersebut dibuat mengikut spesifikasi, tahap pencapaian dan tempoh yang telah dipersetujui.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN2',2,'Memberi dan menerima maklum balas daripada ahli pasukan mengenai isu-isu yang dihadapi, cara-cara penyelesaian yang telah/perlu diambil untuk memperbaiki tahap kecekapan dan keberkesanan operasi jabatan atau bahagian; Menyelidik dan meneliti aduan pelanggan dalaman dan luaran yang diterima dengan tujuan untuk mengenal pasti punca dan cara-cara untuk mempertingkatkan tahap kepuasan pelanggan; Mengambil langkah-langkah proaktif dan konstruktif untuk mengatasi cabaran-cabaran dan halangan-halangan yang berpotensi untuk menjejas kelancaran sistem penyampaian perkhidmatan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN2',3,'Membangunkan strategi yang mantap untuk mempertingkatkan kecekapan perancangan dan pelaksanaan operasi; Mengkaji dan menganalisis operasi dan mencadangkan langkah-langkah proaktif dan konstruktif untuk meningkatkan kualiti, kecekapan dan keberkesanan operasi; Membangunkan pelan tindakan susulan untuk mengurus risiko dan implikasi yang terhasil akibat pelaksanaan langkah-langkah peningkatan sistem operasi yang baharu.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN2',4,'Membangunkan model operasi yang optimum untuk menyokong pencapaian bersesuaian dengan visi, misi dan matlamat universiti; Mengkaji dan menganalisis kecekapan, keberkesanan, kualiti dan risikomenyeluruh proses operasimencadangkan langkah-langkah intervensi yang proaktif dan konstruktif untuk mencapai sinergi yang terbaik bagi jabatan; Memperkenalkan kaedah-kaedah baharu dan inovatif untuk memantapkan dan meningkatkan kelancaran, kecekapan dan keberkesanan operasi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN2',5,'Membimbing dan memupuk budaya kecemerlangan di dalam pengurusan operasi universiti; Meneraju perubahan berterusan di dalam mencapai tahap kecemerlangan pengurusan operasi universiti; Meningkatkan jaringan kolaborasi di peringkat kebangsaan dan antarabangsa bagi mendapatkan pengiktirafan kecemerlangan universiti.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN3',1,'Merancang keperluan kewangan tahunan dengan mengenal pasti program-program, aktiviti-aktiviti dan kegunaan sumber yang memerlukan pembiayaan kewangan; Menyediakan kertas cadangan untuk memohon peruntukan sumber kewangan untuk kegunaan operasi dalam tempoh yang ditetapkan; Merancang, memantau dan mengawal perbelanjaan kewangan secara berhemah berpandukan Arahan Perbendaharaan berkaitan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN3',2,'Meneliti laporan varian (perbezaan di antara kos perbelanjaan sebenar dan peruntukan diluluskan) dan mencadangkan tundakan yang sesuai untuk diambil bagi menangani isu tersebut; Merancang penggunaan kewangan dan aset mengikut keutamaan, kesesuaian fungsi dan keperluan operasi untuk kegunaan optimum dan mengelakkan pembaziran; Melapor sebarang aktiviti atau transaksi yang meragukan untuk tindakan seterusnya.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN3',3,'Merancang dan melaksana strategi bagi memperolehi dana kewangan yang mencukupi bagi membiayai operasi atau projek selaras dengan keperluan operasi; Mengkaji, mengenal pasti dan menganalisis puncapunca berlakunya ketirisan sistem penyampaian dan mencadangkan langkah-langkah intervensi kekal untuk menghalang ketirisan tersebut berulang. Menyemak dan meneliti; kewajaran alasan dan kesahihan dokumen-dokumen bagi setiap permohonan untuk perolehan produk dan servis mengikut prosedur kewangan yang ditetapkan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN3',4,'Memperkasakan aplikasi teknologi maklumat dalam menganalisis dan menilai maklumat kewangan dan juga dalam membuat anggaran atau jangkaan perbelanjaan dan pendapatan universiti; Mengenal pasti cara-cara kreatif untuk meningkatkan kecekapan dan keberkesanan penggunaan sumber dan mengawal kos operasi; Mengawal selia dan menilai penggunaan dan penyenggaraan aset menurut prosedur yang ditetapkan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN3',5,'Memperkenalkan sistem, kaedah dan tatakerja baharu untuk membangunkan sistem pengurusan kewangan dan aset yang mampan; Memantapkan pembangunan dan penggunaan sistem atau aplikasi teknologi universiti bagi membantu pengurusan kewangan dan aset yang lebih tepat, cekap dan berkesan; Membimbing pasukan untuk memantapkan sistem pengurusan kewangan dan aset yang lestari.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN4',1,'Menyiapkan dokumen rasmi seperti minit mesyuarat dan laporan bulanan mengikut templat atau format yang sedia ada; Membantu menyediakan dan menyiapkan kertas cadangan mengikut garis panduan prosedur dan piawaian yang ditetapkan; Merujuk kepada ketua/ penyelia mengenai hal-hal berbangkit berkaitan dengan situasi bukan rutin.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN4',2,'Mengetahui keperluan kumpulan sasar yang perlu dipenuhi oleh dokumen rasmi dan mengumpul maklumat yang lengkap dan tepat ke arah menyediakan dan menyiapkan dokumen tersebut; Merangka dan merancang isi kandungan sesuatu dokumen rasmi bertujuan untuk menyampaikan maklumat atau mesej yang tepat, jelas dan sesuai untuk kumpulan sasar; Menyemak dan memastikan penyediaan dan penyiapan dokumen rasmi disempurnakan dengan teliti mengikut protokol dan piawaian yang tepat sebelum dimajukan kepada pihak atasan/ lain.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN4',3,'Mengenal pasti dan merangka strategi sesuai ke arah menghasilkan makluman, laporan, cadangan, jawapan bertulis dan sebagainya untuk memenuhi keperluan kumpulan sasar; Mengkaji, menganalisis dan merumus implikasi penyediaan sesuatu dokumen rasmi daripada sudut penyampaian mesej, respons, keberhasilan, kepuasan kumpulan sasar dan sebagainya; Merancang, memantau dan mengawal penyediaan dan penyiapan dokumen rasmi dan melakukan intervensi bersesuaian dan tepat pada masanya untuk memastikan matlamat jabatan tercapai.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN4',4,'Membangunkan bakat untuk membantu penghasilan dokumen rasmi yang berkualiti tinggi; Memperkenalkan kaedah baharu dalam penyediaan dokumen rasmi yang sesuai dengan keperluan semasa; Memudahcara dan menyokong proses pembangunan kakitangan di dalam meningkatkan kemahiran di dalam penyediaan dokumen rasmi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('GN4',5,'Menggerakkan budaya berkualiti dan kecemerlangan di dalam penyediaan dokumen rasmi; Memperkasa inisiatif utama dalam usaha membudayakan sistem penulisan dokumen rasmi yang unggul di pelbagai peringkat dalam universiti; Menghargai dan menggalakkan kolaborasi dan kerjasama pelbagai pihak bagi memantapkan proses dan kualiti penyediaan dokumen rasmi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP1',1,'Memahami visi, misi dan objektif universiti dan menterjemah ke dalam keputusan seharian; Menganalisis masalah dan trend organisasi dalaman dan luaran yang boleh memberi kesan kepada visi universiti; Menjelaskan strategi universiti kepada kakitangan bagi meningkatkan pemahaman dan pelaksanaan yang berkesan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP1',2,'Menetapkan arah di dalam menghurai dan menjangka sesuatu situasi atau masalah secara jelas dan terperinci; Menjajarkan pemikiran secara tersusun di dalam menyelesaikan sesuatu persoalan atau masalah; Menunjukkan komitmen yang tinggi untuk mencari penyelesaian secara kreatif dan terbaik di dalam sesuatu permasalahan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP1',3,'Memudahcara pencapaian objektif strategik dengan memperuntukkan sumber dan memfokuskan usaha pasukan; Menterjemahkan strategi dengan jelas kepada pasukan untuk meningkatkan pemahaman, penghargaan dan penerimaan; Menganalisis kekuatan, kelemahan, peluang dan ancaman situasi dan mengembangkan pendekatan dan objektif jangka panjang berdasarkan penemuan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP1',4,'Menerapkan kaedah-kaedah, amalan-amalan terbaik dan sistem pemikiran strategik yang kontemporari dan terkini untuk memacu kreativiti dan inovasi di peringkat universiti; Memantau kesan dan punca permasalahan keseluruhan dan mengenal pasti tindakan penyelesaian dan kesannya kepada universiti; Menggerakkan penglibatan semua pihak berkepentingan dalam mengenal pasti punca serta tindakan penyelesaian yang diperlukan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP1',5,'Menguasai persekitaran politik universiti di dalam proses mempengaruhi dan melibatkan warga universiti membina pemikiran strategik; Memberi khidmat nasihat di dalam membina pemikiran strategi di peringkat dalaman dan luaran; Menanam budaya berfikiran strategik di kalangan warga universiti untuk meningkatkan daya saing universiti.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP2',1,'Mengetahui pihak pemegang taruh luaran dan dalaman yang relevan dengan peranan semasa; Berkongsi secara proaktif maklumat yang diperoleh daripada penglibatan pemegang taruh luaran dengan cara yang bermanfaat dan tepat pada masanya; Membina hubungan positif dengan rakan sebaya dan rakan sekerja dengan cara membantu menyampaikan strategi pemegang taruh secara keseluruhan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP2',2,'Menyenaraikan organisasi berpotensi untuk mewujudkan jaringan dan kolaborasi strategik; Menyediakan pelan perancangan untuk membangunkan program jaringan dan kolaborasi strategik dengan pemegang taruh; Menyediakan pelan tindakan pelaksanaan program jaringan dan kolaborasi strategi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP2',3,'Merangka strategi yang memberi impak positif di dalam menjalin dan membina kerjasama strategik dengan pemegang taruh yang dikenalpasti; Menyediakan pasukan pelaksana pelan tindakan jaringan kolaborasi strategik; Memantau perjalanan program jaringan kolaborasi strategik.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP2',4,'Menilai keberkesanan kolaborasi semasa dan yang relevan untuk mencapai strategi objektif organisasi; Mencipta peluang untuk memulakan kolaborasi baharu yang akan memudahkan pencapaian matlamat strategik organisasi; Mengkaji dan menganalisis keberkesanan program jaringan dan kolaborasi strategik dan mencadangkan langkah-langkah intervensi.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP2',5,'Merangka pendekatan-pendekatan baharu di dalam memperkasa jaringan dan kolaborasi strategik di peringkat nasional dan antarabangsa; Memberi khidmat nasihat di dalam memimpin agenda jaringan dan kolaborasi strategik di peringkat dalaman dan luaran universiti; Mengembangkan kedudukan sebagai pemimpin di kalangan rangkaian luaran untuk digunakan bagi memaksimumkan pengaruh dan kredibiliti universiti di kalangan pemegang taruh.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP3',1,'Menganalisis keperluan bakat kepimpinan yang menyumbang kepada kejayaan universiti; Mendapatkan maklumat berkaitan untuk menyokong pelan pembangunan pemimpin; Menyalurkan maklumat pembangunan kepimpinan berkaitan kepada pihak berkepentingan di dalam universiti.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP3',2,'Menyediakan pelan membangunkan bakat kepimpinan; Menjalankan sisi perkongsian bagi membangunkan bakat kepimpinan; Mendapatkan maklum balas dari pelbagai pihak berkepentingan bagi memantapkan pelan bimbingan pembangunan bakat kepimpinan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP3',3,'Memantau proses pemilihan calon bakat kepimpinan; Memantau dan menilai keberkesanan pelaksanaan pelan pembangunan kepimpinan; Menjalankan sesi latihan pembangunan bakat secara berterusan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP3',4,'Merangka pelan pembangunan kepimpinan di peringkat universiti; Memperkenalkan pendekatan dan kaedah terbaik di dalam memperkasa pembangunan kepimpinan di peringkat universiti; Membimbing pembimbing dan mentor untuk memperkasa proses pembangunan bakat kepimpinan di peringkat universiti.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP3',5,'Memberi khidmat nasihat kepada jawatankuasa pembangunan bakat kepimpinan di peringkat dalaman dan luaran; Menjadi pakar rujuk bagi aspek pembangunan kepimpinan di peringkat organisasi dan antarabangsa; Mencetuskan idea baharu di luar kebiasaan bagi memacu pembangunan bakat kepimpinan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP4',1,'Menganalisis keperluan kepada penggubalan dan penguatkuasaan dasar universiti; Menilai keutamaan kepada penggubalan dan penguatkuasaan dasar bagi mencapai matlamat universiti; Menggerakkan pihak-pihak yang berkepentingan di dalam proses penggubalan dan penguatkuasaan dasar.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP4',2,'Meningkatkan proses dan prosedur penggubalan dan penguatkuasaan dasar dengan jelas; Menyediakan rangka dasar untuk kelulusan kerajaan dan melakukan pindaan dan penambahbaikan kepada draf tersebut; Mengkaji impak dan implikasi penguatkuasaan sesuatu dasar dan mencadangkan penambahbaikan kepada rangka dasar untuk kelulusan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP4',3,'Memudahcara proses mendapatkan maklum balas dan pandangan perundangan daripada pihak berkepentingan untuk menggubal dan menguatkuasakan dasar yang menepati keperluan universiti; Menyediakan dan menyiapkan laporan berkenaan sesuatu dasar untuk kelulusan pihak perundangan dan pimpinan universiti; Melakukan audit terhadap penguatkuasaan dasar dan menyediakan laporan mengenai hasil audit tersebut dan cadangan penambahbaikan terhadap proses penguatkuasaan dasar.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP4',4,'Mencadangkan penambahbaikan kepada dasar untuk menangani isu-isu dan situasi-situasi yang utama yang dihadapi oleh universiti; Mencadangkan pindaan atau pemansuhan sesuatu dasar yang didapati kurang sesuai atau tidak lagi boleh diguna pakai; Mengadaptasikan amalan-amalan terbaik untuk meningkatkan tahap kecekapan dan keberkesanan penggubalan dan penguatkuasaan dasar di peringkat universiti.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP4',5,'Mengusulkan pendekatan baharu untuk dilaksanakan untuk mencapai dasar yang proaktif, inovatif dan berwawasan; Merangka strategi dan pendekatan baharu yang mengurangkan kerenah birokrasi untuk membolehkan kakitangan menggubal dan menguatkuasakan dasar dengan cekap dan berkesan; Memberi khidmat nasihat dengan pihak-pihak di luar universiti untuk menyeragamkan tatacara penggubalan dan penguatkuasaan dasar di universiti.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP5',1,'Menggalakkan penyertaan dan penglibatan pemegang taruh dalam aktiviti pengurusan perubahan; Mengambil inisiatif dalam mencari cara baharu untuk mencipta atau menambah nilai dalam perkhidmatan dan proses selaras dengan agenda perubahan; Mendapatkan maklum balas daripada ahli pasukan dalam mengerakkan inisiatif perubahan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP5',2,'Meneliti dan berkongsi maklumat dan pendekatan baharu untuk memenuhi perubahan keperluan universiti; Meningkatkan kesedaran, kefahaman dan buy-in pemegang taruh dalam merangsang proses perubahan; Menguruskan aktiviti dan acara pengurusan perubahan di pejabat dan atau cawangan masing-masing.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP5',3,'Melibatkan orang lain, menyokong dan melaksanakan perubahan untuk meningkatkan program dan perkhidmatan universiti; Menangani tingkah laku dan menjangkakan halangan terhadap perubahan dan inovasi; Menggerakkan tenaga kerja untuk berjaya menerima pakai business model baharu selaras dengan agenda perubahan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP5',4,'Membangunkan strategi menyeluruh untuk menyediakan organisasi menghadapi perubahan; Membangunkan pendekatan proaktif di dalam mengurus pemegang taruh mengharungi perubahan; Mengukur dan memantau kemajuan pelaksanaan program perubahan untuk memastikan faedah perubahan yang mampan.') on conflict do nothing;
insert into tna_competency_levels (competency_code, level, indicator_ms) values ('KP5',5,'Menggerakkan strategi proaktif mengurus pemegang taruh mengharungi perubahan; Menciptakan inisiatif untuk memacu warga universiti tampil dengan cara baharu untuk menyokong kemampuan organisasi untuk berjaya; Menguruskan risiko yang berkaitan dengan perubahan melalui perancangan kontingensi yang sesuai yang berdasarkan pembelajaran yang diperoleh melalui pengalaman perubahan.') on conflict do nothing;
